cypress_script:
describe('Progress Bar Functionality', () => {
  it('should start the progress bar when clicked', () => {
    cy.visit('https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    cy.url().should('include', '/progress-bar');
    // Add an assertion here to verify the progress bar is in a starting state, if applicable
  });

  it('should not change URL when button is clicked while progress is ongoing', () => {
    cy.get('#startStopButton').click();
    cy.get('#startStopButton').click();
    cy.url().should('include', '/progress-bar');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Progress Bar Functionality', () => {
  test('should start the progress bar when clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/progress-bar');
    await page.click('#startStopButton');
    await expect(page).toHaveURL(/progress-bar/);
    // Add an assertion here to verify the progress bar is in a starting state, if applicable
  });

  test('should not change URL when button is clicked while progress is ongoing', async ({ page }) => {
    await page.click('#startStopButton');
    await page.click('#startStopButton');
    await expect(page).toHaveURL(/progress-bar/);
  });
});
